//
// This is only a SKELETON file for the 'Zebra Puzzle' exercise. It's been been provided as a
// convenience to get you started writing code faster.
//

const NATIONALITIES = ['Englishman', 'Spaniard', 'Ukrainian', 'Norwegian', 'Japanese'];
const COLORS = ['Red', 'Ivory', 'Green', 'Yellow', 'Blue'];
const PETS = ['Dog', 'Fox', 'Snail', 'Horse', 'Zebra'];
const DRINKS = ['Coffee', 'Tea', 'Milk', 'Orange juice', 'Water'];
const HOBBIES = ['Dancing', 'Reading', 'Painter', 'Football', 'Chess'];

export class ZebraPuzzle {
  constructor() {
    this.solution = this.solve();
  }

  waterDrinker() {
    return this.solution.waterDrinker;
  }

  zebraOwner() {
    return this.solution.zebraOwner;
  }

  solve() {
    const houses = [0, 1, 2, 3, 4].map(() => ({}));

    // House 0 is the Norwegian, and house 2 drinks milk.
    houses[0].nationality = 'Norwegian';
    houses[2].drink = 'Milk';

    const assign = (house, category, value) => {
      houses[house][category] = value;
    };

    const isSatisfied = () => {
      for (let h = 0; h < 5; h++) {
        const house = houses[h];
        const { nationality, color, pet, drink, hobby } = house;

        // 2. The Englishman lives in the red house.
        if (nationality === 'Englishman' && color !== 'Red') return false;
        if (color === 'Red' && nationality !== 'Englishman') return false;

        // 3. The Spaniard owns the dog.
        if (nationality === 'Spaniard' && pet !== 'Dog') return false;
        if (pet === 'Dog' && nationality !== 'Spaniard') return false;

        // 4. The person in the green house drinks coffee.
        if (color === 'Green' && drink !== 'Coffee') return false;
        if (drink === 'Coffee' && color !== 'Green') return false;

        // 5. The Ukrainian drinks tea.
        if (nationality === 'Ukrainian' && drink !== 'Tea') return false;
        if (drink === 'Tea' && nationality !== 'Ukrainian') return false;

        // 7. The snail owner likes to go dancing.
        if (pet === 'Snail' && hobby !== 'Dancing') return false;
        if (hobby === 'Dancing' && pet !== 'Snail') return false;

        // 8. The person in the yellow house is a painter.
        if (color === 'Yellow' && hobby !== 'Painter') return false;
        if (hobby === 'Painter' && color !== 'Yellow') return false;

        // 13. The person who plays football drinks orange juice.
        if (hobby === 'Football' && drink !== 'Orange juice') return false;
        if (drink === 'Orange juice' && hobby !== 'Football') return false;

        // 14. The Japanese person plays chess.
        if (nationality === 'Japanese' && hobby !== 'Chess') return false;
        if (hobby === 'Chess' && nationality !== 'Japanese') return false;
      }

      // 6. The green house is immediately to the right of the ivory house.
      for (let h = 0; h < 4; h++) {
        if (houses[h].color === 'Ivory' && houses[h + 1].color !== 'Green') return false;
        if (houses[h + 1].color === 'Green' && houses[h].color !== 'Ivory') return false;
      }

      // 11. The person who enjoys reading lives next to the person with the fox.
      for (let h = 0; h < 5; h++) {
        if (houses[h].hobby === 'Reading') {
          const neighbors = [houses[h - 1], houses[h + 1]].filter(Boolean);
          if (!neighbors.some((n) => n.pet === 'Fox')) return false;
        }
        if (houses[h].pet === 'Fox') {
          const neighbors = [houses[h - 1], houses[h + 1]].filter(Boolean);
          if (!neighbors.some((n) => n.hobby === 'Reading')) return false;
        }
      }

      // 12. The painter's house is next to the house with the horse.
      for (let h = 0; h < 5; h++) {
        if (houses[h].hobby === 'Painter') {
          const neighbors = [houses[h - 1], houses[h + 1]].filter(Boolean);
          if (!neighbors.some((n) => n.pet === 'Horse')) return false;
        }
        if (houses[h].pet === 'Horse') {
          const neighbors = [houses[h - 1], houses[h + 1]].filter(Boolean);
          if (!neighbors.some((n) => n.hobby === 'Painter')) return false;
        }
      }

      // 15. The Norwegian lives next to the blue house.
      if (houses[1].color !== 'Blue') return false;

      return true;
    };

    const categories = ['nationality', 'color', 'pet', 'drink', 'hobby'];
    const values = [NATIONALITIES, COLORS, PETS, DRINKS, HOBBIES];

    const backtrack = (categoryIndex) => {
      if (categoryIndex === categories.length) {
        return isSatisfied();
      }

      const category = categories[categoryIndex];
      for (const value of values[categoryIndex]) {
        // Skip values already used in another house.
        if (houses.some((h) => h[category] === value)) continue;

        // Skip values whose house is already assigned a different value.
        const unassigned = houses.filter((h) => h[category] === undefined);
        for (const house of unassigned) {
          assign(house, category, value);
          if (backtrack(categoryIndex + 1)) return true;
          house[category] = undefined;
        }
      }

      return false;
    };

    backtrack(0);

    const waterDrinker = houses.find((h) => h.drink === 'Water').nationality;
    const zebraOwner = houses.find((h) => h.pet === 'Zebra').nationality;

    return { waterDrinker, zebraOwner };
  }
}

